                            shooting_tier = tier + 1;
                        } else if (tier == 8) {
                            shooting_tier = 7;
                        }
                        int effect_index = shooting_tier - 1;
                        if (effect_index > 6)
                            effect_index = 6;
                        g_sound_effect_manager.Play(effect_index + 1);
                        ScoreAdd(SUBGOLDY_SCORE_RING, 0);
                        continue;
                    }
