                            } else {
                                float rate = game->subgame_rate;
                                float scaled_rate = rate * rate * 0.0040000002f;
                                velocity.z = scaled_rate * -8.0f;
                                damage_gauge.Take(1.0f, 0);
                            }
                        } else {
                            game->slug_hazards.slots[m].Kill();
